    key = 'assistance:reference:' + hashlib.sha256(fingerprint.encode()).hexdigest()
    ttl = max(0, min(3600, int(getattr(settings, 'GEMINI_CACHE_TTL_SECONDS', 3600))))
    try:
        cached = cache.get(key) if ttl else None
    except Exception:
