name: Django CI

on:
  pull_request:
    branches: [main]
  push:
    branches: [main]
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: django-ci-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

jobs:
  checks:
    name: Django checks and tests
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    env:
      APP_ENV: test
      DJANGO_DEBUG: 'false'
      # Public test fixture, never a deployed credential. CI needs no real secrets.
      DJANGO_SECRET_KEY: REDACTED
      DJANGO_ALLOWED_HOSTS: localhost,127.0.0.1,testserver
      DJANGO_SSL_REDIRECT: 'false'
      APP_RELEASE: ${{ github.sha }}
    steps:
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
        with:
          persist-credentials: false
      - uses: actions/setup-python@ece7cb06caefa5fff74198d8649806c4678c61a1 # v6
        with:
          python-version-file: .python-version
          cache: pip
          cache-dependency-path: requirements.txt
      - name: Install locked dependencies
        run: python -m pip install --require-hashes -r requirements.txt
      - name: Check configuration and migration consistency
        run: |
          python manage.py check
          python manage.py makemigrations --check --dry-run
      - name: Collect production static assets
        run: python manage.py collectstatic --noinput
      - name: Run isolated database and deployment tests
        run: python manage.py test --verbosity 2
      - name: Check production settings
        env:
          APP_ENV: production
          DJANGO_SSL_REDIRECT: 'true'
        run: python manage.py check --deploy --fail-level ERROR
